import{_ as t,o as r,c as o,a3 as d}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Payments Stripe refunds (1.7.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payments Stripe refunds (1.7.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/payments-stripe-refunds-1-7-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payments Stripe refunds (1.7.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/payments-stripe-refunds-1-7-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/payments-stripe-refunds-1-7-0-production-readiness.md","filePath":"deployment/payments-stripe-refunds-1-7-0-production-readiness.md","lastUpdated":1792251546000}'),n={name:"deployment/payments-stripe-refunds-1-7-0-production-readiness.md"};function a(s,e,i,c,l,p){return r(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="payments-stripe-refunds-1-7-0-—-production-readiness-audit" tabindex="-1">Payments Stripe refunds (1.7.0) — Production Readiness Audit <a class="header-anchor" href="#payments-stripe-refunds-1-7-0-—-production-readiness-audit" aria-label="Permalink to &quot;Payments Stripe refunds (1.7.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-17</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — feature Pest green; headed payments Playwright <strong>10/10</strong></td></tr><tr><td><strong>Scope</strong></td><td>Live Stripe refunds for gateway customer payments; ledger, invoice allocations, and accounting stay in sync</td></tr><tr><td><strong>Catalog</strong></td><td><strong>payments 1.6.0 → 1.7.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/payments">Payments user guide</a> · <a href="/developer-guide/payments">Payments developer guide</a> · <a href="/api/tenant-v1-payments">Payments API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Posted payments with <code>gateway_provider=stripe</code> refund the captured PaymentIntent on the <strong>workspace</strong> Stripe account, then record the existing ledger refund. Cash, bank, cheque, and other methods stay ledger-only. A Stripe Dashboard refund is recorded once when <code>refund.created</code> arrives.</p><p><strong>Go / No-Go:</strong> <strong>Go.</strong> Migrate-only. No new permission. Central Cashier is not used. Operators add <code>refund.created</code> to the existing customer-payments webhook.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong></td></tr><tr><td>Stripe call happens before the ledger write; a Stripe error leaves the payment posted</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Manual refund never calls Stripe</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Checkout Session id (<code>cs_</code>) is resolved to a PaymentIntent and stored</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Duplicate <code>refund.created</code> does not double <code>amount_refunded</code></td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Secret key follows <code>gateway_mode</code>, then the capture note, then the current connection mode</td><td><strong>Pass</strong> (code review)</td></tr><tr><td><code>payments.refund</code> still authorizes the staff route</td><td><strong>Pass</strong> (existing Pest)</td></tr><tr><td>Catalog migrate-only bump + CatalogSeeder companion <strong>1.7.0</strong></td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Refund dialog explains an empty, zero, or over-balance amount and keeps submit disabled</td><td><strong>Pass</strong> (headed Playwright)</td></tr><tr><td>Ledger refund of $20 on an $80 posted payment restores $20 of invoice balance and shows the refund row</td><td><strong>Pass</strong> (headed Playwright, Accounting installed on the demo workspace)</td></tr><tr><td>Stripe payment shows <strong>Refund via Stripe</strong> and does not submit a live charge</td><td><strong>Pass</strong> (headed Playwright)</td></tr><tr><td>Payments Playwright, headed, one worker</td><td><strong>Pass</strong> — <strong>10/10</strong> (<code>test:e2e:payments:headed</code>)</td></tr></tbody></table><p>Feature Pest on 2026-10-17: <strong>14 passed / 99 assertions</strong> (Stripe refund, existing ledger refund, portal checkout, catalog 1.6.0 and 1.7.0 bumps).</p><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td><code>POST /payments/{id}/refund</code> still requires <code>payments.refund</code></td><td>Pass</td></tr><tr><td>Workspace secret keys stay on <code>TenantStripeApi</code>; Central <code>StripeGateway</code> is not called</td><td>Pass</td></tr><tr><td>Webhook still verifies the active-mode signing secret before <code>refund.created</code></td><td>Pass</td></tr><tr><td>Unknown PaymentIntents are ignored</td><td>Pass</td></tr><tr><td><code>stripe_refund_id</code> is unique, so a staff refund and the webhook cannot both insert</td><td>Pass</td></tr><tr><td>Refund responses expose the Stripe refund id, not the secret key</td><td>Pass</td></tr></tbody></table><hr><h2 id="findings-disposition" tabindex="-1">Findings disposition <a class="header-anchor" href="#findings-disposition" aria-label="Permalink to &quot;Findings disposition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>Medium</td><td>Refund submit was disabled for a bad amount with no explanation</td><td><strong>Fixed</strong> — the dialog shows “Enter a refund amount.”, “Refund amount must be greater than zero.”, or “Refund amount cannot exceed the refundable balance.” Headed test covers all three and then records a $20 ledger refund</td></tr><tr><td><strong>I1</strong></td><td>Info</td><td>A new refund attempt uses a new idempotency key. If Stripe succeeds and the ledger write fails, a retry can refund again until <code>refund.created</code> books the first id</td><td><strong>Accepted</strong> — webhook <code>refund.created</code> is required in the go-live steps. The unique <code>stripe_refund_id</code> stops a double ledger row</td></tr><tr><td><strong>I2</strong></td><td>Info</td><td>Playwright’s bundled ffmpeg download timed out, so the workflow spec runs on system Chrome with video off</td><td><strong>Accepted</strong> — not a product defect. Authz and Stripe specs passed in the same headed run</td></tr></tbody></table><hr><h2 id="headed-browser-coverage" tabindex="-1">Headed browser coverage <a class="header-anchor" href="#headed-browser-coverage" aria-label="Permalink to &quot;Headed browser coverage&quot;">​</a></h2><p><code>npx playwright test e2e/tests/payments --project=tenant --headed --workers=1</code> on 2026-10-17. Result: <strong>10 passed</strong>.</p><p>One demo login inside the payments workflow, then the Stripe shared-session spec and the send-permission spec:</p><ol><li>Create a payment, allocate it to an invoice, post it</li><li>Open <strong>Record refund</strong>, clear the amount, enter an amount over the balance, confirm both errors, cancel</li><li>Download and email the receipt, void the payment, confirm the invoice returns to unpaid</li><li>Open a Stripe-captured payment, confirm <strong>Refund via Stripe</strong>, enter 0, confirm the error, cancel without calling Stripe</li><li>Post an $80 cash payment, submit a $20 refund, confirm “Refund recorded”, “partially refunded”, the $20 refund row, and the invoice balance of $20</li><li>Stripe dialog: enable without keys, save sandbox keys, bogus live secret fails the connection test, disconnect</li><li>Staff without <code>payments.send</code> can download a receipt and cannot email it</li></ol><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> — <code>gateway_mode</code>, <code>stripe_refund_id</code>, catalog <strong>1.7.0</strong>. Do not <code>db:seed</code>.</li><li>Deploy the SPA and hard-refresh.</li><li>Add <code>refund.created</code> to the workspace Stripe webhook. Keep the Checkout events.</li><li>Sandbox smoke: portal Pay now, then <strong>Refund via Stripe</strong> for a partial amount.</li></ol>',22)])])}const g=t(n,[["render",a]]);export{h as __pageData,g as default};
